fn runtime_root(input:&std::path::Path,allowed:&std::path::Path)->Result<std::path::PathBuf,String>{
 use std::path::Component;
 if !input.is_absolute()||input.components().any(|c|matches!(c,Component::ParentDir)){return Err("Harness requires an absolute confined local root".into())}
 #[cfg(windows)]{
  use std::path::Prefix;
  if !matches!(input.components().next(),Some(Component::Prefix(p)) if matches!(p.kind(),Prefix::Disk(_)|Prefix::VerbatimDisk(_))){return Err("Harness refuses network/device roots".into())}
 }
 let canonical=input.canonicalize().map_err(|_|"Harness root unavailable")?;let allowed=allowed.canonicalize().map_err(|_|"Harness owner root unavailable")?;
 if canonical==allowed||!canonical.starts_with(&allowed){return Err("Harness root escapes owned output".into())}
 // Canonical paths prove confinement; runtime resources retain the ordinary
 // drive spelling required by the existing journal's strict local-path guard.
 let text=canonical.to_str().ok_or("Harness root encoding unavailable")?;
 let ordinary=std::path::PathBuf::from(text.strip_prefix(r"\\?\").unwrap_or(text));
 if !ordinary.is_absolute()||ordinary.to_string_lossy().starts_with(r"\\")||ordinary.canonicalize().ok().as_ref()!=Some(&canonical){return Err("Harness ordinary path does not identify confined root".into())}
 Ok(ordinary)
}
