const HARNESS_STACK_BYTES:usize=16*1024*1024;
fn harness_thread<T:Send+'static>(work:impl FnOnce()->T+Send+'static)->T{
 std::thread::Builder::new().name("se1-composition-harness".into()).stack_size(HARNESS_STACK_BYTES).spawn(work).expect("bounded composition thread creation").join().unwrap_or_else(|panic|std::panic::resume_unwind(panic))
}
async fn execute(root:std::path::PathBuf){
 eprintln!("SE1_HARNESS bounded thread stack_bytes={HARNESS_STACK_BYTES}; boxed scenario; deadline_seconds=300");
 tokio::time::timeout(Duration::from_secs(300),Box::pin(run(&root))).await.expect("bounded SE1 composition deadline; cooperative service cleanup requested");
}
// Type layout only: the async body is never constructed or polled, so this
// diagnostic cannot start the service, create a Core, or contact a database.
fn future_bytes<F:std::future::Future>(_:impl FnOnce(&'static std::path::Path)->F)->usize{std::mem::size_of::<F>()}
#[test]fn se1_harness_stack_layout_without_service(){
 let run_bytes=future_bytes(run);let wrapper_bytes=future_bytes(|root|async move{tokio::time::timeout(Duration::from_secs(300),run(root)).await});
 assert!(run_bytes<=128*1024,"retain Core instances on the heap; do not grow the scenario frame back to its failed size");
 eprintln!("SE1_LAYOUT core_bytes={} run_future_bytes={run_bytes} timeout_wrapper_bytes={wrapper_bytes}",std::mem::size_of::<Client>());
}
#[test]fn se1_harness_boxed_construction_without_service(){
 fn execute_bytes<F:std::future::Future>(_:impl FnOnce(std::path::PathBuf)->F)->usize{std::mem::size_of::<F>()}
 assert!(execute_bytes(execute)<1024,"outer executor must retain a pointer, not the composition frame");
 harness_thread(||tauri::async_runtime::block_on(async{
  // Construct the same boxed scenario and timer on the actual harness stack,
  // but NEVER poll them: run's first statement and Service::start cannot run.
  let scenario=Box::pin(run(std::path::Path::new("unpolled-stack-diagnostic")));
  let deadline=tokio::time::timeout(Duration::from_secs(300),scenario);
  tokio::task::yield_now().await;
  drop(deadline);
  eprintln!("SE1_CONSTRUCTION boxed scenario/timeout constructed and dropped unpolled; stack_bytes={HARNESS_STACK_BYTES}; execute_future_bytes={}",execute_bytes(execute));
 }));
}
