fn held(c:&Client){assert!(c.pending.lock().unwrap().as_ref().is_none_or(|p|!p.release));if let Some(b)=bridge(c){assert!(b.pending.lock().unwrap().as_ref().is_none_or(|p|!p.release));}}
async fn waiting_a(c:&mut Client,h:&mut health::HealthRunner<MemoryStore>)->local::WaitingMarker{c.create_fixture(false).await.unwrap();until(c,h,"canonical initial bundle",20,true,|c|c.pending.lock().unwrap().as_ref().is_some_and(|p|p.startup_ready)).await;claim(c,false).await;until(c,h,"saved waiting A",25,true,|c|c.waiting_startup_marker().is_some()).await;held(c);c.waiting_startup_marker().unwrap()}
async fn staged(c:&mut Client,h:&mut health::HealthRunner<MemoryStore>)->entry::View{until(c,h,"passive B ready",20,true,|c|current_b(c).is_some_and(|v|v.phase==entry::Phase::Staged)).await;let v=current_b(c).unwrap();assert!(!bridge(c).unwrap().worker.fresh_started());assert!(original(c,&v).activation_original().is_none());v}
